[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellStream Platform — Integrated Energy Data Management</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
  :root {
    --navy: #15295A;
    --navy-dark: #0D1B2A;
    --navy-mid: #1B2838;
    --green: #6CC24A;
    --gray-dark: #3C424B;
    --blue-accent: #00B4D8;
    --blue-mid: #0077B6;
    --white: #FFFFFF;
    --text-muted: #94A3B8;
    --border: rgba(255,255,255,0.1);
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Inter', sans-serif; background: var(--navy-dark); color: var(--white); line-height: 1.6; }
  a { color: inherit; text-decoration: none; }

  /* NAV */
  nav {
    position: fixed; top: 0; left: 0; right: 0; z-index: 100;
    background: rgba(13,27,42,0.95); backdrop-filter: blur(12px);
    border-bottom: 1px solid var(--border);
    padding: 0 2rem; height: 68px;
    display: flex; align-items: center; justify-content: space-between;
  }
  .nav-logo { display: flex; align-items: center; gap: 0.5rem; font-size: 1.25rem; font-weight: 800; letter-spacing: -0.02em; }
  .nav-logo span { color: var(--green); }
  .nav-links { display: flex; align-items: center; gap: 2rem; }
  .nav-links a { font-size: 0.875rem; font-weight: 500; color: var(--text-muted); transition: color 0.2s; }
  .nav-links a:hover { color: var(--white); }
  .nav-dropdown { position: relative; }
  .nav-dropdown > a { display: flex; align-items: center; gap: 0.3rem; cursor: pointer; }
  .nav-dropdown > a::after { content: '▾'; font-size: 0.7rem; }
  .dropdown-menu {
    display: none; position: absolute; top: calc(100% + 1rem); left: 0;
    background: var(--navy-mid); border: 1px solid var(--border);
    border-radius: 8px; padding: 0.5rem; min-width: 200px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.4);
  }
  .nav-dropdown:hover .dropdown-menu { display: block; }
  .dropdown-menu a { display: block; padding: 0.6rem 1rem; font-size: 0.875rem; color: var(--text-muted); border-radius: 6px; transition: all 0.2s; }
  .dropdown-menu a:hover { background: rgba(255,255,255,0.05); color: var(--white); }
  .btn-demo {
    background: var(--green); color: var(--navy-dark); font-weight: 700;
    padding: 0.55rem 1.25rem; border-radius: 6px; font-size: 0.875rem;
    transition: all 0.2s; white-space: nowrap;
  }
  .btn-demo:hover { background: #7DD55A; transform: translateY(-1px); }
  .nav-mobile-toggle { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 4px; }
  .nav-mobile-toggle span { width: 24px; height: 2px; background: var(--white); border-radius: 2px; transition: all 0.3s; }
  .mobile-menu {
    display: none; position: fixed; top: 68px; left: 0; right: 0; bottom: 0;
    background: var(--navy-dark); padding: 2rem; overflow-y: auto; z-index: 99;
    flex-direction: column; gap: 1.5rem;
  }
  .mobile-menu.open { display: flex; }
  .mobile-menu a { font-size: 1.125rem; font-weight: 500; color: var(--text-muted); padding: 0.75rem 0; border-bottom: 1px solid var(--border); }
  .mobile-menu a:hover { color: var(--white); }

  /* HERO */
  .hero {
    min-height: 100vh; padding: 7rem 2rem 5rem;
    background: linear-gradient(135deg, var(--navy-dark) 0%, var(--navy) 60%, #0a1f3c 100%);
    display: flex; align-items: center; justify-content: center;
    text-align: center; position: relative; overflow: hidden;
  }
  .hero::before {
    content: ''; position: absolute; inset: 0;
    background: radial-gradient(ellipse 80% 60% at 50% 0%, rgba(108,194,74,0.08) 0%, transparent 70%),
                radial-gradient(ellipse 60% 40% at 80% 80%, rgba(0,180,216,0.06) 0%, transparent 60%);
  }
  .hero-grid {
    position: absolute; inset: 0; opacity: 0.04;
    background-image: linear-gradient(var(--white) 1px, transparent 1px),
                      linear-gradient(90deg, var(--white) 1px, transparent 1px);
    background-size: 60px 60px;
  }
  .hero-content { position: relative; z-index: 1; max-width: 900px; }
  .hero-badge {
    display: inline-flex; align-items: center; gap: 0.5rem;
    background: rgba(108,194,74,0.12); border: 1px solid rgba(108,194,74,0.3);
    color: var(--green); font-size: 0.75rem; font-weight: 600; letter-spacing: 0.08em;
    padding: 0.35rem 0.9rem; border-radius: 100px; margin-bottom: 1.5rem;
  }
  .hero h1 {
    font-size: clamp(2.2rem, 5vw, 4rem); font-weight: 900; line-height: 1.1;
    letter-spacing: -0.03em; margin-bottom: 1.5rem;
  }
  .hero h1 span { color: var(--green); }
  .hero p { font-size: clamp(1rem, 2vw, 1.2rem); color: var(--text-muted); max-width: 660px; margin: 0 auto 2.5rem; }
  .hero-btns { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
  .btn-primary {
    background: var(--green); color: var(--navy-dark); font-weight: 700;
    padding: 0.85rem 2rem; border-radius: 8px; font-size: 1rem; transition: all 0.2s;
  }
  .btn-primary:hover { background: #7DD55A; transform: translateY(-2px); box-shadow: 0 8px 24px rgba(108,194,74,0.3); }
  .btn-outline {
    border: 1.5px solid rgba(255,255,255,0.25); color: var(--white);
    padding: 0.85rem 2rem; border-radius: 8px; font-size: 1rem; font-weight: 600; transition: all 0.2s;
  }
  .btn-outline:hover { border-color: rgba(255,255,255,0.6); background: rgba(255,255,255,0.05); }
  .hero-stats {
    display: flex; gap: 3rem; justify-content: center; margin-top: 4rem;
    flex-wrap: wrap;
  }
  .hero-stat { text-align: center; }
  .hero-stat .num { font-size: 2.5rem; font-weight: 800; color: var(--green); line-height: 1; }
  .hero-stat .lbl { font-size: 0.8rem; color: var(--text-muted); font-weight: 500; margin-top: 0.3rem; }

  /* PRODUCT BANNER */
  .product-banner {
    background: linear-gradient(90deg, var(--navy) 0%, #1a3a6b 100%);
    border-top: 1px solid var(--border); border-bottom: 1px solid var(--border);
    padding: 1.5rem 2rem;
  }
  .product-banner-inner {
    max-width: 1200px; margin: 0 auto;
    display: flex; align-items: center; justify-content: space-between; gap: 2rem; flex-wrap: wrap;
  }
  .product-banner-badge {
    background: var(--green); color: var(--navy-dark); font-size: 0.7rem;
    font-weight: 800; letter-spacing: 0.1em; padding: 0.25rem 0.6rem; border-radius: 4px;
  }
  .product-banner h3 { font-size: 1.25rem; font-weight: 700; margin: 0; }
  .product-banner p { font-size: 0.875rem; color: var(--text-muted); }
  .btn-sm {
    background: transparent; border: 1.5px solid var(--green); color: var(--green);
    padding: 0.5rem 1.2rem; border-radius: 6px; font-size: 0.875rem; font-weight: 600; transition: all 0.2s;
  }
  .btn-sm:hover { background: var(--green); color: var(--navy-dark); }

  /* SECTIONS */
  section { padding: 5rem 2rem; }
  .container { max-width: 1200px; margin: 0 auto; }
  .section-label {
    font-size: 0.75rem; font-weight: 700; letter-spacing: 0.12em;
    color: var(--green); text-transform: uppercase; margin-bottom: 0.75rem;
  }
  .section-title { font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 800; letter-spacing: -0.02em; margin-bottom: 1rem; }
  .section-desc { color: var(--text-muted); max-width: 620px; font-size: 1rem; line-height: 1.7; }

  /* USE CASES */
  .use-cases { background: var(--navy-mid); }
  .use-cases-header { margin-bottom: 3rem; }
  .use-cases-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 1.5rem;
    margin-bottom: 2.5rem;
  }
  .use-case-card {
    background: rgba(255,255,255,0.03); border: 1px solid var(--border);
    border-radius: 12px; padding: 1.75rem; cursor: pointer;
    transition: all 0.3s; position: relative; overflow: hidden;
  }
  .use-case-card::before {
    content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px;
    background: linear-gradient(90deg, var(--green), var(--blue-accent));
    transform: scaleX(0); transition: transform 0.3s; transform-origin: left;
  }
  .use-case-card:hover { border-color: rgba(108,194,74,0.3); background: rgba(108,194,74,0.04); transform: translateY(-3px); }
  .use-case-card:hover::before { transform: scaleX(1); }
  .use-case-icon { font-size: 1.75rem; margin-bottom: 1rem; }
  .use-case-card h3 { font-size: 1rem; font-weight: 700; margin-bottom: 0.5rem; }
  .use-case-card p { font-size: 0.875rem; color: var(--text-muted); line-height: 1.6; }
  .use-cases-cta { text-align: center; margin-top: 2rem; }

  /* INDUSTRY TABS */
  .industry-tabs-section { background: var(--navy-dark); }
  .tabs-nav {
    display: flex; gap: 0.25rem; flex-wrap: wrap;
    background: rgba(255,255,255,0.04); border-radius: 10px; padding: 0.4rem;
    margin-bottom: 2rem; border: 1px solid var(--border);
  }
  .tab-btn {
    padding: 0.6rem 1.25rem; border-radius: 7px; font-size: 0.875rem; font-weight: 600;
    cursor: pointer; transition: all 0.2s; border: none; background: transparent; color: var(--text-muted);
  }
  .tab-btn.active { background: var(--navy); color: var(--white); box-shadow: 0 2px 8px rgba(0,0,0,0.3); }
  .tab-btn:hover:not(.active) { color: var(--white); background: rgba(255,255,255,0.05); }
  .tab-panel { display: none; }
  .tab-panel.active { display: grid; grid-template-columns: 1fr 1fr; gap: 3rem; align-items: center; }
  .tab-content h3 { font-size: 1.5rem; font-weight: 700; margin-bottom: 1rem; }
  .tab-content p { color: var(--text-muted); margin-bottom: 1.5rem; line-height: 1.7; }
  .tab-features { list-style: none; display: flex; flex-direction: column; gap: 0.75rem; }
  .tab-features li { display: flex; align-items: flex-start; gap: 0.75rem; font-size: 0.9rem; color: var(--text-muted); }
  .tab-features li::before { content: '✓'; color: var(--green); font-weight: 700; flex-shrink: 0; margin-top: 0.1rem; }
  .tab-visual {
    background: rgba(255,255,255,0.02); border: 1px solid var(--border);
    border-radius: 16px; padding: 2rem; height: 280px;
    display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden;
  }

  /* PLATFORM ECOSYSTEM DIAGRAM */
  .platform-diagram-section { background: var(--navy-mid); }
  .ecosystem-diagram {
    display: grid; grid-template-columns: 1fr auto 1fr; gap: 0; align-items: center;
    margin-top: 3rem; max-width: 900px; margin-left: auto; margin-right: auto;
  }
  .eco-pillar {
    background: rgba(255,255,255,0.03); border: 1px solid var(--border);
    border-radius: 16px; padding: 2rem; text-align: center; position: relative;
    transition: all 0.3s;
  }
  .eco-pillar:hover { border-color: rgba(108,194,74,0.4); background: rgba(108,194,74,0.03); }
  .eco-pillar .icon { font-size: 2.5rem; margin-bottom: 1rem; }
  .eco-pillar h3 { font-size: 1rem; font-weight: 700; margin-bottom: 0.5rem; color: var(--green); }
  .eco-pillar p { font-size: 0.8rem; color: var(--text-muted); line-height: 1.5; }
  .eco-center {
    display: flex; flex-direction: column; align-items: center; justify-content: center;
    padding: 1rem; position: relative;
  }
  .eco-center-hub {
    width: 80px; height: 80px; background: linear-gradient(135deg, var(--green), var(--blue-accent));
    border-radius: 50%; display: flex; align-items: center; justify-content: center;
    font-size: 1.5rem; font-weight: 900; color: var(--navy-dark); box-shadow: 0 0 40px rgba(108,194,74,0.3);
  }
  .eco-connector {
    display: flex; align-items: center; justify-content: center; padding: 0 0.5rem;
  }
  .connector-line { width: 40px; height: 2px; background: linear-gradient(90deg, rgba(108,194,74,0.3), rgba(108,194,74,0.7)); }
  .eco-three { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 1.5rem; margin-top: 3rem; }

  /* COMPANY CULTURE */
  .culture-section {
    background: linear-gradient(135deg, var(--navy) 0%, #0a1f3c 100%);
    position: relative; overflow: hidden;
  }
  .culture-section::before {
    content: ''; position: absolute; right: -100px; top: -100px;
    width: 400px; height: 400px;
    background: radial-gradient(circle, rgba(108,194,74,0.08) 0%, transparent 70%);
  }
  .culture-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 4rem; align-items: center; }
  .culture-content .section-title { font-size: clamp(1.5rem, 3vw, 2.25rem); }
  .culture-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 2rem; }
  .culture-metric { background: rgba(255,255,255,0.04); border: 1px solid var(--border); border-radius: 10px; padding: 1.25rem; text-align: center; }
  .culture-metric .num { font-size: 1.75rem; font-weight: 800; color: var(--green); }
  .culture-metric .lbl { font-size: 0.8rem; color: var(--text-muted); margin-top: 0.25rem; }
  .culture-visual {
    background: rgba(255,255,255,0.02); border: 1px solid var(--border);
    border-radius: 20px; padding: 2.5rem; text-align: center;
  }
  .world-map-svg { width: 100%; max-width: 400px; }

  /* RENEWABLES CTA */
  .renewables-section {
    background: linear-gradient(135deg, #0a2a1a 0%, var(--navy-dark) 100%);
    border-top: 1px solid rgba(108,194,74,0.15);
  }
  .renewables-inner {
    display: flex; align-items: center; justify-content: space-between; gap: 3rem; flex-wrap: wrap;
  }
  .renewables-content { flex: 1; min-width: 280px; }
  .renewables-badge {
    display: inline-flex; align-items: center; gap: 0.5rem;
    background: rgba(108,194,74,0.1); border: 1px solid rgba(108,194,74,0.25);
    color: var(--green); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08em;
    padding: 0.3rem 0.75rem; border-radius: 100px; margin-bottom: 1rem;
  }

  /* FOOTER */
  footer { background: #080F1A; border-top: 1px solid var(--border); padding: 4rem 2rem 2rem; }
  .footer-inner { max-width: 1200px; margin: 0 auto; }
  .footer-top { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 3rem; margin-bottom: 3rem; }
  .footer-brand .logo { font-size: 1.25rem; font-weight: 800; margin-bottom: 1rem; }
  .footer-brand .logo span { color: var(--green); }
  .footer-brand p { font-size: 0.85rem; color: var(--text-muted); max-width: 260px; line-height: 1.6; }
  .footer-col h4 { font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; color: var(--white); margin-bottom: 1rem; text-transform: uppercase; }
  .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.6rem; }
  .footer-col ul li a { font-size: 0.85rem; color: var(--text-muted); transition: color 0.2s; }
  .footer-col ul li a:hover { color: var(--green); }
  .footer-bottom { border-top: 1px solid var(--border); padding-top: 2rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; }
  .footer-bottom p { font-size: 0.8rem; color: var(--text-muted); }
  .footer-logins { display: flex; gap: 1rem; flex-wrap: wrap; }
  .footer-logins a { font-size: 0.8rem; color: var(--text-muted); border: 1px solid var(--border); padding: 0.3rem 0.75rem; border-radius: 4px; transition: all 0.2s; }
  .footer-logins a:hover { color: var(--white); border-color: rgba(255,255,255,0.3); }

  /* COOKIE BANNER */
  .cookie-banner {
    position: fixed; bottom: 1.5rem; left: 50%; transform: translateX(-50%);
    background: var(--navy-mid); border: 1px solid var(--border);
    border-radius: 12px; padding: 1.25rem 1.75rem;
    display: flex; align-items: center; gap: 1.5rem; flex-wrap: wrap;
    max-width: 700px; width: calc(100% - 3rem);
    z-index: 200; box-shadow: 0 20px 50px rgba(0,0,0,0.4);
    animation: slideUp 0.4s ease;
  }
  .cookie-banner.hidden { display: none; }
  @keyframes slideUp { from { transform: translate(-50%, 100px); opacity: 0; } to { transform: translate(-50%, 0); opacity: 1; } }
  .cookie-banner p { font-size: 0.85rem; color: var(--text-muted); flex: 1; min-width: 200px; line-height: 1.5; }
  .cookie-btns { display: flex; gap: 0.75rem; }
  .btn-cookie-accept { background: var(--green); color: var(--navy-dark); font-weight: 700; padding: 0.5rem 1.25rem; border-radius: 6px; font-size: 0.85rem; border: none; cursor: pointer; transition: all 0.2s; }
  .btn-cookie-accept:hover { background: #7DD55A; }
  .btn-cookie-decline { background: transparent; color: var(--text-muted); border: 1px solid var(--border); padding: 0.5rem 1.25rem; border-radius: 6px; font-size: 0.85rem; cursor: pointer; transition: all 0.2s; }
  .btn-cookie-decline:hover { color: var(--white); border-color: rgba(255,255,255,0.3); }

  /* RESPONSIVE */
  @media (max-width: 768px) {
    nav .nav-links { display: none; }
    nav .btn-demo { display: none; }
    .nav-mobile-toggle { display: flex; }
    .tab-panel.active { grid-template-columns: 1fr; }
    .ecosystem-diagram { grid-template-columns: 1fr; }
    .eco-connector { display: none; }
    .eco-three { grid-template-columns: 1fr; }
    .culture-inner { grid-template-columns: 1fr; }
    .culture-metrics { grid-template-columns: 1fr 1fr; }
    .culture-visual { display: none; }
    .footer-top { grid-template-columns: 1fr 1fr; }
    .footer-brand { grid-column: 1 / -1; }
    .renewables-inner { flex-direction: column; text-align: center; }
  }
  @media (max-width: 480px) {
    .hero-stats { gap: 1.5rem; }
    .use-cases-grid { grid-template-columns: 1fr; }
    .footer-top { grid-template-columns: 1fr; }
    .culture-metrics { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>

<!-- NAV -->
<nav>
  <a href="index.html" class="nav-logo">Well<span>Stream</span></a>
  <div class="nav-links">
    <div class="nav-dropdown">
      <a href="#">Platform</a>
      <div class="dropdown-menu">
        <a href="platform-overview.html">Platform Overview</a>
        <a href="security.html">Security</a>
        <a href="integration.html">Integration</a>
      </div>
    </div>
    <a href="index.html#use-cases">Solutions</a>
    <a href="index.html#culture">Company</a>
    <a href="request-demo.html">Contact</a>
  </div>
  <a href="request-demo.html" class="btn-demo">Request A Demo</a>
  <div class="nav-mobile-toggle" onclick="toggleMobile()">
    <span></span><span></span><span></span>
  </div>
</nav>
<div class="mobile-menu" id="mobileMenu">
  <a href="platform-overview.html">Platform Overview</a>
  <a href="security.html">Security</a>
  <a href="integration.html">Integration</a>
  <a href="index.html#use-cases">Solutions</a>
  <a href="request-demo.html" style="color:var(--green);font-weight:700;">Request A Demo</a>
</div>

<!-- HERO -->
<section class="hero">
  <div class="hero-grid"></div>
  <div class="hero-content">
    <div class="hero-badge">⚡ Energy Data Platform</div>
    <h1>GET REAL-TIME DATA ACROSS YOUR <span>ENTIRE OPERATION</span></h1>
    <p>The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
    <div class="hero-btns">
      <a href="platform-overview.html" class="btn-primary">Explore the Platform</a>
      <a href="request-demo.html" class="btn-outline">Request A Demo</a>
    </div>
    <div class="hero-stats">
      <div class="hero-stat"><div class="num">80+</div><div class="lbl">Energy Companies</div></div>
      <div class="hero-stat"><div class="num">89%</div><div class="lbl">Digital Transformation</div></div>
      <div class="hero-stat"><div class="num">31%</div><div class="lbl">ROI in Year One</div></div>
    </div>
  </div>
</section>

<!-- PRODUCT BANNER -->
<div class="product-banner">
  <div class="product-banner-inner">
    <div style="display:flex;align-items:center;gap:1rem;flex-wrap:wrap;">
      <span class="product-banner-badge">NEW</span>
      <div>
        <div style="font-size:0.75rem;font-weight:600;color:var(--text-muted);letter-spacing:0.06em;text-transform:uppercase;">Featured Product</div>
        <h3>WellStream Innova</h3>
      </div>
      <p>Real-Time Directional Data Exchange for drilling operations</p>
    </div>
    <a href="platform-overview.html" class="btn-sm">Learn More</a>
  </div>
</div>

<!-- USE CASES -->
<section class="use-cases" id="use-cases">
  <div class="container">
    <div class="use-cases-header">
      <div class="section-label">Use Cases</div>
      <h2 class="section-title">See the WellStream Platform in Action</h2>
      <p class="section-desc">From drilling to production, land to water, watch how WellStream transforms every phase of your operations. Streamline workflows, unlock real-time insights, and make every decision count with seamless, end-to-end data integration.</p>
    </div>
    <div class="use-cases-grid">
      <div class="use-case-card">
        <div class="use-case-icon">⛏️</div>
        <h3>Drilling &amp; Completions Management</h3>
        <p>Centralize drilling programs, daily reports, and well design data in one accessible hub.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">📊</div>
        <h3>Production Operations Oversight</h3>
        <p>Monitor production volumes, allocations, and decline curves with real-time dashboards.</p>
      </div>
