<style>
  :root {
    --navy: #15295A; --navy-dark: #0D1B2A; --navy-mid: #1B2838;
    --green: #6CC24A; --gray-dark: #3C424B;
    --blue-accent: #00B4D8; --blue-mid: #0077B6;
    --white: #FFFFFF; --text-muted: #94A3B8; --border: rgba(255,255,255,0.1);
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: 'Inter', sans-serif; background: var(--navy-dark); color: var(--white); line-height: 1.6; }
  a { color: inherit; text-decoration: none; }

  nav { position: fixed; top: 0; left: 0; right: 0; z-index: 100; background: rgba(13,27,42,0.95); backdrop-filter: blur(12px); border-bottom: 1px solid var(--border); padding: 0 2rem; height: 68px; display: flex; align-items: center; justify-content: space-between; }
  .nav-logo { font-size: 1.25rem; font-weight: 800; letter-spacing: -0.02em; }
  .nav-logo span { color: var(--green); }
  .nav-links { display: flex; align-items: center; gap: 2rem; }
  .nav-links a { font-size: 0.875rem; font-weight: 500; color: var(--text-muted); transition: color 0.2s; }
  .nav-links a:hover { color: var(--white); }
  .nav-dropdown { position: relative; }
  .nav-dropdown > a { display: flex; align-items: center; gap: 0.3rem; cursor: pointer; }
  .nav-dropdown > a::after { content: '▾'; font-size: 0.7rem; }
  .dropdown-menu { display: none; position: absolute; top: calc(100% + 1rem); left: 0; background: var(--navy-mid); border: 1px solid var(--border); border-radius: 8px; padding: 0.5rem; min-width: 200px; box-shadow: 0 20px 40px rgba(0,0,0,0.4); }
  .nav-dropdown:hover .dropdown-menu { display: block; }
  .dropdown-menu a { display: block; padding: 0.6rem 1rem; font-size: 0.875rem; color: var(--text-muted); border-radius: 6px; transition: all 0.2s; }
  .dropdown-menu a:hover { background: rgba(255,255,255,0.05); color: var(--white); }
  .btn-demo { background: var(--green); color: var(--navy-dark); font-weight: 700; padding: 0.55rem 1.25rem; border-radius: 6px; font-size: 0.875rem; transition: all 0.2s; }
  .btn-demo:hover { background: #7DD55A; }
  .nav-mobile-toggle { display: none; flex-direction: column; gap: 5px; cursor: pointer; padding: 4px; }
  .nav-mobile-toggle span { width: 24px; height: 2px; background: var(--white); border-radius: 2px; }
  .mobile-menu { display: none; position: fixed; top: 68px; left: 0; right: 0; bottom: 0; background: var(--navy-dark); padding: 2rem; z-index: 99; flex-direction: column; gap: 1.5rem; }
  .mobile-menu.open { display: flex; }
  .mobile-menu a { font-size: 1.125rem; color: var(--text-muted); padding: 0.75rem 0; border-bottom: 1px solid var(--border); }

  .container { max-width: 1200px; margin: 0 auto; }
  section { padding: 5rem 2rem; }
  .section-label { font-size: 0.75rem; font-weight: 700; letter-spacing: 0.12em; color: var(--green); text-transform: uppercase; margin-bottom: 0.75rem; }
  .section-title { font-size: clamp(1.75rem, 3vw, 2.5rem); font-weight: 800; letter-spacing: -0.02em; margin-bottom: 1rem; }
  .section-desc { color: var(--text-muted); max-width: 620px; font-size: 1rem; line-height: 1.7; }

  .page-hero {
    padding: 9rem 2rem 5rem;
    background: linear-gradient(135deg, #060d18 0%, var(--navy) 60%, #0d1e3a 100%);
    position: relative; overflow: hidden;
  }
  .page-hero::before { content: ''; position: absolute; inset: 0; background: radial-gradient(ellipse 80% 60% at 30% 50%, rgba(0,180,216,0.08) 0%, transparent 70%); }
  .hero-shield { position: absolute; right: 8%; top: 50%; transform: translateY(-50%); opacity: 0.07; font-size: 18rem; line-height: 1; pointer-events: none; }

  /* SECURITY TABS */
  .sec-tabs-section { background: var(--navy-mid); }
  .tabs-nav { display: flex; gap: 0.25rem; background: rgba(255,255,255,0.04); border-radius: 10px; padding: 0.4rem; border: 1px solid var(--border); width: fit-content; margin-bottom: 2.5rem; }
  .tab-btn { padding: 0.65rem 2rem; border-radius: 7px; font-size: 0.9rem; font-weight: 600; cursor: pointer; transition: all 0.2s; border: none; background: transparent; color: var(--text-muted); }
  .tab-btn.active { background: var(--navy-dark); color: var(--white); box-shadow: 0 2px 8px rgba(0,0,0,0.3); }
  .tab-btn:hover:not(.active) { color: var(--white); background: rgba(255,255,255,0.05); }
  .tab-panel { display: none; }
  .tab-panel.active { display: block; }

  /* SECURITY FEATURES LIST */
  .sec-features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 1.5rem; margin-top: 2rem; }
  .sec-feature-card { background: rgba(255,255,255,0.03); border: 1px solid var(--border); border-radius: 14px; padding: 1.75rem; display: flex; gap: 1.25rem; transition: all 0.3s; }
  .sec-feature-card:hover { border-color: rgba(0,180,216,0.3); background: rgba(0,180,216,0.03); }
  .sec-icon { width: 52px; height: 52px; border-radius: 12px; background: rgba(0,180,216,0.1); border: 1px solid rgba(0,180,216,0.25); display: flex; align-items: center; justify-content: center; font-size: 1.5rem; flex-shrink: 0; }
  .sec-feature-content h3 { font-size: 0.95rem; font-weight: 700; margin-bottom: 0.5rem; color: var(--white); }
  .sec-feature-content p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.6; }

  /* SOC COMPLIANCE */
  .soc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 2rem; margin-top: 2rem; }
  .soc-card { background: rgba(255,255,255,0.03); border: 1px solid var(--border); border-radius: 14px; padding: 2rem; text-align: center; transition: all 0.3s; }
  .soc-card:hover { border-color: rgba(108,194,74,0.3); }
  .soc-badge { width: 80px; height: 80px; border-radius: 50%; background: linear-gradient(135deg, rgba(108,194,74,0.15), rgba(0,180,216,0.15)); border: 2px solid rgba(108,194,74,0.4); display: flex; align-items: center; justify-content: center; font-size: 1.75rem; margin: 0 auto 1rem; }
  .soc-card h3 { font-size: 1.1rem; font-weight: 800; color: var(--green); margin-bottom: 0.5rem; }
  .soc-card p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.6; }

  /* AZURE SECTION */
  .azure-section { background: var(--navy-dark); }
  .azure-inner { display: grid; grid-template-columns: 1fr 1fr; gap: 5rem; align-items: center; }
  .azure-diagram { background: rgba(255,255,255,0.02); border: 1px solid var(--border); border-radius: 20px; padding: 2.5rem; }
  .infra-layers { display: flex; flex-direction: column; gap: 1rem; }
  .infra-layer { padding: 1rem 1.5rem; border-radius: 10px; display: flex; align-items: center; gap: 1rem; font-size: 0.9rem; font-weight: 600; }
  .layer-app { background: rgba(108,194,74,0.1); border: 1px solid rgba(108,194,74,0.3); color: var(--green); }
  .layer-mid { background: rgba(0,180,216,0.1); border: 1px solid rgba(0,180,216,0.3); color: var(--blue-accent); }
  .layer-infra { background: rgba(21,41,90,0.5); border: 1px solid rgba(255,255,255,0.15); color: var(--text-muted); }
  .layer-icon { font-size: 1.25rem; }
  .sla-badges { display: flex; gap: 1rem; flex-wrap: wrap; margin-top: 1.5rem; }
  .sla-badge { background: rgba(255,255,255,0.04); border: 1px solid var(--border); border-radius: 8px; padding: 0.6rem 1rem; font-size: 0.8rem; font-weight: 600; color: var(--text-muted); }
  .sla-badge span { color: var(--green); font-weight: 800; }

  /* COMPLIANCE CTA */
  .compliance-cta { background: linear-gradient(135deg, var(--navy) 0%, #0a1f3c 100%); text-align: center; }
  .compliance-cta-inner { max-width: 700px; margin: 0 auto; }
  .btn-primary { background: var(--green); color: var(--navy-dark); font-weight: 700; padding: 0.85rem 2rem; border-radius: 8px; font-size: 1rem; transition: all 0.2s; display: inline-block; }
  .btn-primary:hover { background: #7DD55A; transform: translateY(-2px); }
  .btn-outline { border: 1.5px solid rgba(255,255,255,0.25); color: var(--white); padding: 0.85rem 2rem; border-radius: 8px; font-size: 1rem; font-weight: 600; transition: all 0.2s; display: inline-block; }
  .btn-outline:hover { border-color: rgba(255,255,255,0.6); background: rgba(255,255,255,0.05); }

  footer { background: #080F1A; border-top: 1px solid var(--border); padding: 4rem 2rem 2rem; }
  .footer-inner { max-width: 1200px; margin: 0 auto; }
  .footer-top { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 3rem; margin-bottom: 3rem; }
  .footer-brand .logo { font-size: 1.25rem; font-weight: 800; margin-bottom: 1rem; }
  .footer-brand .logo span { color: var(--green); }
  .footer-brand p { font-size: 0.85rem; color: var(--text-muted); max-width: 260px; line-height: 1.6; }
  .footer-col h4 { font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em; color: var(--white); margin-bottom: 1rem; text-transform: uppercase; }
  .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.6rem; }
  .footer-col ul li a { font-size: 0.85rem; color: var(--text-muted); transition: color 0.2s; }
  .footer-col ul li a:hover { color: var(--green); }
  .footer-bottom { border-top: 1px solid var(--border); padding-top: 2rem; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; }
  .footer-bottom p { font-size: 0.8rem; color: var(--text-muted); }
  .footer-logins { display: flex; gap: 1rem; flex-wrap: wrap; }
  .footer-logins a { font-size: 0.8rem; color: var(--text-muted); border: 1px solid var(--border); padding: 0.3rem 0.75rem; border-radius: 4px; transition: all 0.2s; }
  .footer-logins a:hover { color: var(--white); border-color: rgba(255,255,255,0.3); }

  @media (max-width: 768px) {
    nav .nav-links { display: none; }
    nav .btn-demo { display: none; }
    .nav-mobile-toggle { display: flex; }
    .azure-inner { grid-template-columns: 1fr; }
    .soc-grid { grid-template-columns: 1fr; }
    .footer-top { grid-template-columns: 1fr 1fr; }
    .footer-brand { grid-column: 1 / -1; }
    .hero-shield { display: none; }
    .tabs-nav { flex-wrap: wrap; }
  }
  @media (max-width: 480px) {
    .sec-features-grid { grid-template-columns: 1fr; }
    .footer-top { grid-template-columns: 1fr; }
  }
</style>
</head>
