<script>
  function toggleMobile() {
    document.getElementById('mobileMenu').classList.toggle('open');
  }

  const form = document.getElementById('demoForm');
  const success = document.getElementById('formSuccess');

  const validators = {
    firstName: v => v.trim().length > 0,
    lastName: v => v.trim().length > 0,
    email: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()),
    company: v => v.trim().length > 0,
    jobTitle: v => v.trim().length > 0,
    country: v => v !== ''
  };
  const errorMessages = {
    firstName: 'First name is required.',
    lastName: 'Last name is required.',
    email: 'A valid business email address is required.',
    company: 'Company name is required.',
    jobTitle: 'Job title is required.',
    country: 'Please select your country.'
  };

  function validateField(name) {
    const input = document.getElementById(name);
    const errorEl = document.getElementById(name + 'Error');
    if (!validators[name]) return true;
    const valid = validators[name](input.value);
    input.classList.toggle('error', !valid);
    if (errorEl) {
      errorEl.classList.toggle('visible', !valid);
      errorEl.textContent = valid ? '' : errorMessages[name];
    }
    return valid;
  }

  // Live validation on blur
  Object.keys(validators).forEach(name => {
    const input = document.getElementById(name);
    if (input) {
      input.addEventListener('blur', () => validateField(name));
      input.addEventListener('input', () => {
        if (input.classList.contains('error')) validateField(name);
      });
    }
  });

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const fields = Object.keys(validators);
    const results = fields.map(validateField);
    const allValid = results.every(Boolean);
    if (!allValid) {
      // Scroll to first error
      const firstError = document.querySelector('.form-input.error');
      if (firstError) firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return;
    }
    // Simulate submission
    const btn = form.querySelector('.form-submit');
    btn.textContent = 'Submitting...';
    btn.disabled = true;
    setTimeout(() => {
      form.style.display = 'none';
      success.style.display = 'block';
    }, 1200);
  });
</script>
